WITH enriched AS (SELECT *, SUM(sqft) OVER (ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, AVG(sqft) OVER (ORDER BY sqft, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS sqft_avg_6, SUM(sqft) OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sqft, ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date DESC, id) AS seq_no FROM stores WHERE city NOT IN ('Singapore', 'Chiang Mai')), ranked AS (SELECT id, opened_date, sqft, running_sqft, sqft_avg_6, cumulative_sqft, seq_no FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY sqft_avg_6 NULLS FIRST, id) AS rank_in_group FROM enriched) ranked WHERE rank_in_group = 1), metrics AS (SELECT id, opened_date, sqft, cumulative_sqft, seq_no, PERCENT_RANK() OVER (ORDER BY sqft NULLS FIRST) AS sqft_percent_rank, LAST_VALUE(sqft_avg_6) IGNORE NULLS OVER (ORDER BY sqft_avg_6, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_sqft_avg_6, LEAD(running_sqft, 1) OVER (ORDER BY sqft_avg_6, id) AS next_running_sqft, SUM(seq_no) OVER (ORDER BY running_sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_seq_no, NTILE(5) OVER (ORDER BY sqft DESC, id) AS sqft_bucket FROM ranked), eligible AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM orders ch WHERE ch.store_id = s.id AND ch.customer_id IS NOT NULL)), not_flagged AS (SELECT s.* FROM eligible s WHERE EXISTS (SELECT 1 FROM inventory x WHERE x.store_id = s.id AND x.quantity BETWEEN 165 AND 180)), eligible_stores AS (SELECT s.* FROM not_flagged s WHERE EXISTS (SELECT 1 FROM orders x WHERE x.store_id = s.id AND x.order_date < s.opened_date)), kept AS (SELECT s.* FROM eligible_stores s WHERE NOT EXISTS (SELECT 1 FROM store_sales c WHERE c.store_id = s.id AND c.sale_date < s.opened_date)) SELECT id, opened_date, cumulative_sqft, seq_no, last_known_sqft_avg_6, next_running_sqft, cumulative_seq_no, COUNT(next_running_sqft) OVER (ORDER BY sqft_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_next_running_sqft, AVG(next_running_sqft) OVER (ORDER BY sqft_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_next_running_sqft, MIN(next_running_sqft) OVER (ORDER BY sqft_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_next_running_sqft, MAX(next_running_sqft) OVER (ORDER BY sqft_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_next_running_sqft FROM kept;
